import mongoose from "mongoose";

const messageSchema = new mongoose.Schema(
	{
		senderId: {
			type: mongoose.Schema.Types.ObjectId,
			ref: "User",
			required: true,
		},
		receiverId: {
			type: mongoose.Schema.Types.ObjectId,
			ref: "User",
			required: true,
		},
		message: {
			trim: true,
			maxlength: 2000,
			type: String,
			required: true,
		},
		clientId: {
			type: String,
			maxlength: 64,
		},
		// createdAt, updatedAt
	},
	{ timestamps: true }
);

// Idempotency key generated by the sender's client: retrying the same send can never create a second message.
// Partial index so older messages (no clientId) don't collide with each other.
messageSchema.index(
	{ senderId: 1, clientId: 1 },
	{ unique: true, partialFilterExpression: { clientId: { $type: "string" } } }
);

// speeds up loading a two-way conversation
messageSchema.index({ senderId: 1, receiverId: 1, createdAt: -1 });

const Message = mongoose.model("Message", messageSchema);

export default Message;
